head.script:
scwin.__isShowNormal = function() {
    return WebSquare.wUnit.getObjById("wq_uuid_1").getText() == "hello";
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1').setText('hello')");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "scwin.__isShowNormal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {

    //Function unitTest
    //Created By: Sang.do
    //Created By: 07-Feb-2018
    //end unitTest

}
